input_script:
var src = input.body && typeof input.body === 'object' ? input.body : input;
var query = input.query && typeof input.query === 'object' ? input.query : {};
var merged = {};
var key;
for (key in query) {
  if (Object.prototype.hasOwnProperty.call(query, key)) merged[key] = query[key];
}
if (src.owner !== undefined) merged.owner = src.owner;
if (src.name !== undefined) merged.name = src.name;
if (src.from !== undefined) merged.from = src.from;
if (src.to !== undefined) merged.to = src.to;

function toArray(value) {
  if (Array.isArray(value)) return value;
  if (value && typeof value === 'object') return Object.values(value);
  return value !== undefined && value !== null && value !== '' ? [value] : [];
}

var owners = toArray(merged.owner);
var names = toArray(merged.name);
var count = Math.min(owners.length, names.length);
var specs = [];
for (var i = 0; i < count; i++) {
  specs.push({
    owner: String(owners[i]),
    name: String(names[i]),
    from: merged.from,
    to: merged.to
  });
}

({
  repo_specs: JSON.stringify(specs),
  from: merged.from,
  to: merged.to
})

output_script:
var rows = results['ftpr_data'] || [];
var prs = [];
var standardPipelines = [];
var prowPipelines = [];

for (var i = 0; i < rows.length; i++) {
  var row = rows[i];
  if (row.row_type === 'pr') prs.push(row);
  else if (row.row_type === 'pipeline') standardPipelines.push(row);
  else if (row.row_type === 'prow') prowPipelines.push(row);
}

function timestamp(value) {
  var parsed = new Date(value).getTime();
  return isNaN(parsed) ? 0 : parsed;
}
function byFinishedDate(a, b) {
  return timestamp(a.finished_date) - timestamp(b.finished_date);
}
standardPipelines.sort(byFinishedDate);
prowPipelines.sort(byFinishedDate);
var pipelines = standardPipelines.concat(prowPipelines);

var seenPr = {};
prs = prs.filter(function (pr) {
  if (pr.id === undefined || pr.id === null || pr.id === '') return true;
  var idKey = String(pr.id);
  if (seenPr[idKey]) return false;
  seenPr[idKey] = true;
  return true;
});

function isDraft(value) {
  return value === true || value === 1 || value === '1' || value === 'true';
}

function isAutogenerated(authorName, title, description) {
  if (!authorName) return true;
  var lowerName = String(authorName).toLowerCase();
  var alwaysAIPatterns = [
    /cursor\[bot\]/i,
    /claude\[bot\]/i,
    /copilot/i,
    /copilot-pull-request-reviewer\[bot\]/i
  ];
  for (var patternIndex = 0; patternIndex < alwaysAIPatterns.length; patternIndex++) {
    if (alwaysAIPatterns[patternIndex].test(authorName)) return true;
  }
  if (/github-actions\[bot\]/i.test(authorName)) {
    var content = (title || '') + ' ' + (description || '');
    if (/Code Review Summary/i.test(content) ||
        /Code Review from AI bot/i.test(content) ||
        /Files Reviewed/i.test(content)) return true;
  }
  return lowerName.indexOf('[bot]') >= 0 ||
    lowerName.indexOf('github-actions') >= 0 ||
    lowerName.indexOf('github actions') >= 0 ||
    lowerName.indexOf('dependabot') >= 0 ||
    lowerName.slice(-4) === '-bot' ||
    lowerName.indexOf('red-hat-konflux') >= 0 ||
    lowerName.indexOf('renovate') >= 0 ||
    lowerName.indexOf('fullsend-ai') >= 0 ||
    lowerName.indexOf('snyk') >= 0 ||
    lowerName === 'ci-operator' ||
    lowerName === 'rh-tap-build-team' ||
    lowerName.slice(-6) === '-robot';
}

var validPRs = prs.filter(function (pr) {
  if (pr.status !== 'MERGED') return false;
  if (!pr.merged_date) return false;
  if (isAutogenerated(pr.author_name, pr.title || '', pr.description || '')) return false;
  if (isDraft(pr.is_draft)) return false;
  return true;
});

var pipelinesByCommit = {};
for (var p = 0; p < pipelines.length; p++) {
  var pipeline = pipelines[p];
  var sha = pipeline.head_commit_sha;
  if (!sha || !pipeline.result) continue;
  if (!pipelinesByCommit[sha]) pipelinesByCommit[sha] = [];
  pipelinesByCommit[sha].push({
    result: pipeline.result,
    name: pipeline.pipeline_name || '',
    pipelineId: pipeline.pipeline_id || ''
  });
}

Object.keys(pipelinesByCommit).forEach(function (commitSha) {
  var latestByName = {};
  var commitPipelines = pipelinesByCommit[commitSha];
  for (var pipelineIndex = 0; pipelineIndex < commitPipelines.length; pipelineIndex++) {
    var current = commitPipelines[pipelineIndex];
    var pipelineKey = current.name || current.pipelineId;
    latestByName[pipelineKey] = current;
  }
  pipelinesByCommit[commitSha] = Object.keys(latestByName).map(function (pipelineKey) {
    return latestByName[pipelineKey];
  });
});

function classify(pr) {
  var firstCommitSha = pr.head_commit_sha;
  if (!firstCommitSha) return 'nodata';
  var commitPipelines = pipelinesByCommit[firstCommitSha];
  if (!commitPipelines || commitPipelines.length === 0) return 'nodata';
  for (var resultIndex = 0; resultIndex < commitPipelines.length; resultIndex++) {
    if (commitPipelines[resultIndex].result !== 'SUCCESS') return 'fail';
  }
  return 'pass';
}
var firstTimePassCount = 0;
var prsWithCIData = 0;
var passedPRs = [];
var failedPRs = [];
for (var j = 0; j < validPRs.length; j++) {
  var outcome = classify(validPRs[j]);
  var prRow = { id: validPRs[j].pull_request_key || validPRs[j].title || '', url: validPRs[j].url || '', author: validPRs[j].author_name || '', repo: validPRs[j].base_repo_id || '' };
  if (outcome === 'pass') {
    firstTimePassCount++;
    prsWithCIData++;
    passedPRs.push(prRow);
  } else if (outcome === 'fail') {
    prsWithCIData++;
    failedPRs.push(prRow);
  }
}

var response;
if (validPRs.length === 0) {
  response = {error: 'No merged PRs found for this time period'};
} else if (prsWithCIData === 0) {
  response = {error: 'Merged PRs were found, but none had usable CI results.'};
} else {
  response = {
    type: 'stats',
    label: 'FTPR Key Metrics',
    description: "First Time Pass Rate (FTPR) measures how often code passes all CI checks on the first commit. 'FTPR' is the percentage of merged PRs where the first commit passed all CI pipelines. 'Total Merged PRs' is the count of merged PRs in the time range. 'First-Time Passes' is the count that passed CI on the first attempt. 'CI Coverage' shows how many PRs had CI pipeline data available.",
    lastupdate: null,
    data: {
      metrics: [
        {label: 'FTPR (%)', value: Math.round((firstTimePassCount / prsWithCIData) * 1000) / 10},
        {label: 'Total Merged PRs', value: validPRs.length},
        {label: 'First-Time Passes', value: firstTimePassCount},
        {label: 'CI Coverage', value: prsWithCIData + ' / ' + validPRs.length}
      ],
      extra: {
        config: [
          { location: "appendToAnalytics", type: "openList", field: "passed_prs", template: "Show Passed PRs", labels: [
            { label: "PR", field: "id" },
            { label: "URL", field: "url" },
            { label: "Author", field: "author" },
            { label: "Repo", field: "repo" }
          ] },
          { location: "appendToAnalytics", type: "openList", field: "failed_prs", template: "Show Failed PRs", labels: [
            { label: "PR", field: "id" },
            { label: "URL", field: "url" },
            { label: "Author", field: "author" },
            { label: "Repo", field: "repo" }
          ] }
        ],
        data: {
          passed_prs: passedPRs,
          failed_prs: failedPRs
        }
      }
    }
  };
}
response
